"""Immediate retry wrapper for legacy endpoint integrations."""

from typing import Any, Callable


class TransientError(Exception):
    """A retryable transport failure."""


class PermanentError(Exception):
    """A non-retryable transport failure."""


def call_with_retry(
    endpoint_cfg: dict,
    transport: Callable[[str, int], Any],
) -> dict:
    """Call an injected transport using the legacy retry-count convention."""
    url = endpoint_cfg["url"]
    timeout_ms = endpoint_cfg["timeout_ms"]
    retry = endpoint_cfg["retry"]

    if retry < 0:
        raise ValueError("retry must be non-negative")

    max_attempts = retry + 1

    for attempt in range(1, max_attempts + 1):
        try:
            result = transport(url, timeout_ms)
        except PermanentError as exc:
            return {
                "ok": False,
                "attempts": attempt,
                "result": None,
                "error": {
                    "type": "permanent",
                    "message": str(exc),
                },
            }
        except TransientError as exc:
            if attempt == max_attempts:
                return {
                    "ok": False,
                    "attempts": attempt,
                    "result": None,
                    "error": {
                        "type": "transient",
                        "message": str(exc),
                    },
                }
        else:
            return {
                "ok": True,
                "attempts": attempt,
                "result": result,
                "error": None,
            }

    raise RuntimeError("unreachable")
